 "arsenal_map": {
  "api_sweep": {
   "danger": "safe",
   "desc": "Sweep multiple API paths against a base URL with auth headers, returning FULL response bodies",
   "params": [
    "base*(string): Base URL",
    "paths*(array): List of paths to hit",
    "headers(object): Auth headers dict",
    "method(string): GET or POST (default: GET)"
   ]
  },
  "arsenal_selftest": {
   "danger": "safe",
   "desc": "ROUND 0 BOOT PROTOCOL — run ONCE at mission start",
   "params": [
    "mode(string): 'catalog' (instant map, default) or 'live_local' (catalog + local live tests)"
   ]
  },
  "auth_metadata_poison": {
   "danger": "safe",
   "desc": "Write privileged-looking fields into own user_metadata then re-check access state",
   "params": [
    "base*(string): Base URL of the target service",
    "token*(string): Auth token (JWT/Bearer)",
    "fields(object): Form fields dict"
   ],
   "note": "targeted tool — needs live recon data first"
  },
  "auth_signup_probe": {
   "danger": "safe",
   "desc": "Test if Supabase/auth-style signup is open (no email verification) and mint a session",
   "params": [
    "base*(string): Base URL of the target service",
    "email_domain(string): Domain for the disposable email"
   ],
   "note": "targeted tool — needs live recon data first"
  },
  "auth_state_audit": {
   "danger": "strike",
   "desc": "AUTH 0DAY ENGINE: session-aware state-machine audit of an OAuth2/OIDC/magic-link/MFA flow — infers the flow machine from live HTTP",
   "params": [
    "target*(string): base URL of the auth flow (e.g",
    "report(string): optional path for the markdown acceptance report",
    "json_out(string): optional path for the full verdict() JSON"
   ],
   "note": "targeted tool — needs live recon data first"
  },
  "batch_execute": {
   "danger": "safe",
   "desc": "Run up to 5 independent tool calls CONCURRENTLY: calls=[{tool, args}, ...]",
   "params": [
    "calls*(array): List of {tool, args} calls to run in parallel"
   ]
  },
  "bin_disasm": {
   "danger": "quiet",
   "desc": "RECON: disassemble raw bytes from a binary via capstone — point at an offset (or the PE entry point) and read the actual instructi",
   "params": [
    "path*(string): File or folder path",
    "offset(integer): file offset to start disassembling; omit = entry point for PE",
    "length(integer): length (see tool description)",
    "arch(string): arch (see tool description)"
   ]
  },
  "bin_fuzz_live": {
   "danger": "loud",
   "desc": "EXPLOIT: real-process crash hunting — mutate inputs and run the target binary for real (imports, CRT, loader, relocations), not em",
   "params": [
    "target*(string): Path to the executable",
    "seed(string): Optional seed input file",
    "iterations(integer): iterations (see tool description)",
    "max_total_s(integer): wall-clock budget",
    "per_run_timeout_s(number): per run timeout s (see tool description)",
    "args_template(string): args with {INPUT} placeholder; omit = input fed via stdin"
   ]
  },
  "bin_strings": {
   "danger": "quiet",
   "desc": "RECON: filtered strings extraction from a binary — ASCII runs categorized into URLs, file paths, registry keys, base64-ish blobs a",
   "params": [
    "path*(string): File or folder path",
    "min_len(integer): min len (see tool description)",
    "max_results(integer): max results (see tool description)"
   ]
  },
  "bin_triage": {
   "danger": "quiet",
   "desc": "RECON: static binary triage — hand-rolled PE/COFF + ELF header walk: arch, bits, entry point, section table with per-section entro",
   "params": [
    "path*(string): Path to the binary file"
   ]
  },
  "binary_fuzz_run": {
   "danger": "loud",
   "desc": "EXPLOIT: Coverage-guided binary fuzzing via Unicorn emulation (native C++ hot core)",
   "params": [
    "target_path*(string): Path to binary / raw code to fuzz",
    "corpus_dir(string): Optional seed dir; omitted/null = synthetic seeds from the target itself",
    "mode(string): Scan mode",
    "minutes(integer): minutes (see tool description)",
    "arch(string): arch (see tool description)"
   ],
   "note": "targeted tool — needs live recon data first"
  },
  "c2_pulse": {
   "danger": "loud",
   "desc": "C2: beacon discipline for a deployed shell — N heartbeats with ±jitter on the sleep, rotating UA fingerprints, exponential backoff",
   "params": [
    "shell_url*(any): confirmed webshell URL; {CMD} optional, else ?cmd=",
    "rounds(any): heartbeat count",
    "sleep_s(any): base sleep between heartbeats (jittered ±40%)",
    "param(any): command parameter name",
    "session(any): session id (auto-generated when omitted)"
   ],
   "note": "targeted tool — needs live recon data first"
  },
  "cisa_kev": {
   "danger": "safe",
   "desc": "CISA Known Exploited Vulnerabilities - filter by keyword",
   "params": [
    "keyword*(string): Search keyword"
   ],
   "note": "testable via arsenal_selftest(mode='live_local')"
  },
  "cmd_exec_probe": {
   "danger": "loud",
   "desc": "STRIKE (cmd step 1): OS command injection — separator matrix + echo-marker output capture + time-based blind fallback",
   "params": [
    "url_template*(string): URL with {INJ} placeholder where the command goes",
    "cmd(string): Command to execute on the target",
    "os_flavor(string): Target OS: auto/unix/win",
    "blind(boolean): skip output capture, timing oracle only"
   ],
   "note": "targeted tool — needs live recon data first"
  },
  "cn_fingerprint": {
   "danger": "safe",
   "desc": "Chinese-battlefield stack intelligence: fingerprints, high-risk default paths and default credentials for CN OA/CMS/middleware/net",
   "params": [
    "op*(string): list | fingerprint | creds | search",
    "product_id(string): product id from op=list (e.g",
    "keyword(string): search keyword for op=search (zh or en substring)"
   ]
  },
  "crash_triage_next":

