  .sec-head{display:flex;align-items:center;gap:10px;padding:13px 18px;border-bottom:1px solid var(--border)}
  .sec-head h2{font-size:14px;margin:0;font-weight:650}
  .sec-head .spacer{flex:1}
  table{width:100%;border-collapse:collapse;font-size:13px}
  th{text-align:left;color:var(--dim);font-weight:600;padding:9px 14px;border-bottom:1px solid var(--border);font-size:12px;white-space:nowrap}
  td{padding:9px 14px;border-bottom:1px solid #20262f;vertical-align:middle}
  tr:last-child td{border-bottom:none}
  .dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}
  .dot.live{background:var(--live)} .dot.dead{background:var(--dead)} .dot.limited{background:var(--limited)} .dot.unknown{background:var(--dim)}
  .mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}
  .bar{height:6px;border-radius:3px;background:#222b36;overflow:hidden;min-width:80px}
  .bar > i{display:block;height:100%;background:var(--accent)}
  button{background:var(--panel2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:6px 12px;font-size:13px;cursor:pointer}
  button:hover{border-color:var(--accent)}
  button.primary{background:var(--accent);border-color:var(--accent);color:#fff}
  button.sm{padding:3px 9px;font-size:12px}
  input{background:var(--bg);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:7px 10px;font-size:13px}
  .row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
  .muted{color:var(--dim)}
  .gate{max-width:380px;margin:90px auto;background:var(--panel);border:1px solid var(--border);border-radius:14px;padding:26px}
  .gate h2{margin:0 0 6px} .gate p{color:var(--dim);margin:0 0 16px;font-size:13px}
  .hidden{display:none}
  code{background:#0b0f14;border:1px solid var(--border);padding:1px 5px;border-radius:5px;font-size:12px}
  .toast{position:fixed;bottom:20px;right:20px;background:var(--panel2);border:1px solid var(--accent);padding:12px 16px;border-radius:10px;max-width:420px}
